SET NAMES utf8mb4;
DROP PROCEDURE IF EXISTS nova_de_v3_s001;
DELIMITER $$
CREATE PROCEDURE nova_de_v3_s001()
BEGIN
  DECLARE v_course BIGINT UNSIGNED;
  DECLARE v_level BIGINT UNSIGNED;
  DECLARE v_module BIGINT UNSIGNED;
  DECLARE v_chapter BIGINT UNSIGNED;
  DECLARE v_raha BIGINT UNSIGNED;
  DECLARE v_lena BIGINT UNSIGNED;
  DECLARE v_jonas BIGINT UNSIGNED;
  DECLARE v_l_1 BIGINT UNSIGNED;
  DECLARE v_l_2 BIGINT UNSIGNED;
  DECLARE v_l_3 BIGINT UNSIGNED;
  DECLARE v_l_4 BIGINT UNSIGNED;
  DECLARE v_u_hallo BIGINT UNSIGNED;
  DECLARE v_u_danke BIGINT UNSIGNED;
  DECLARE v_u_tschuss BIGINT UNSIGNED;
  DECLARE v_u_ichheisse BIGINT UNSIGNED;
  DECLARE v_u_wieheisst BIGINT UNSIGNED;
  DECLARE v_u_freut BIGINT UNSIGNED;
  DECLARE v_u_morgen BIGINT UNSIGNED;
  DECLARE v_u_grammar BIGINT UNSIGNED;
  DECLARE v_u_pron_h BIGINT UNSIGNED;
  DECLARE v_u_pron_q BIGINT UNSIGNED;
  DECLARE v_u_cando BIGINT UNSIGNED;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;

  SELECT MIN(id) INTO v_course FROM courses WHERE learning_language='de' AND base_language='fa';
  IF v_course IS NULL THEN
    SET v_course=LAST_INSERT_ID();
  END IF;
  SELECT MIN(id) INTO v_level FROM levels WHERE course_id=v_course AND cefr_level='A1';
  IF v_level IS NULL THEN
    SET v_level=LAST_INSERT_ID();
  END IF;
  SELECT MIN(id) INTO v_module FROM modules WHERE level_id=v_level AND sort_order=1;
  IF v_module IS NULL THEN
    SET v_module=LAST_INSERT_ID();
  END IF;
  SELECT MIN(id) INTO v_raha FROM characters WHERE course_id=v_course AND name='Raha';
  IF v_raha IS NULL THEN INSERT INTO characters (course_id,name,gender,voice_key,profile,metadata) VALUES (v_course,'Raha','female','raha',JSON_OBJECT('role','learner','origin','Iran'),JSON_OBJECT('course','de-fa')); SET v_raha=LAST_INSERT_ID(); END IF;
  SELECT MIN(id) INTO v_lena FROM characters WHERE course_id=v_course AND name='Lena';
  IF v_lena IS NULL THEN INSERT INTO characters (course_id,name,gender,voice_key,profile,metadata) VALUES (v_course,'Lena','female','lena',JSON_OBJECT('role','guide','city','Berlin'),JSON_OBJECT('course','de-fa')); SET v_lena=LAST_INSERT_ID(); END IF;
  SELECT MIN(id) INTO v_jonas FROM characters WHERE course_id=v_course AND name='Jonas';
  IF v_jonas IS NULL THEN INSERT INTO characters (course_id,name,gender,voice_key,profile,metadata) VALUES (v_course,'Jonas','male','jonas',JSON_OBJECT('role','resident','city','Berlin'),JSON_OBJECT('course','de-fa')); SET v_jonas=LAST_INSERT_ID(); END IF;

  SELECT MIN(id) INTO v_chapter FROM chapters WHERE module_id=v_module AND sort_order=1;
  IF v_chapter IS NULL THEN
    SET v_chapter=LAST_INSERT_ID();

    SELECT id INTO v_u_hallo FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:hallo:greeting';
    SELECT id INTO v_u_danke FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:danke:thanks';
    SELECT id INTO v_u_tschuss FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:tschuss:parting';
    SELECT id INTO v_u_ichheisse FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:ich-heisse';
    SELECT id INTO v_u_wieheisst FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:wie-heisst-du';
    SELECT id INTO v_u_freut FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:freut-mich';
    SELECT id INTO v_u_morgen FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:guten-morgen';
    SELECT id INTO v_u_grammar FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:grammar:ich-du-heissen';
    SELECT id INTO v_u_pron_h FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:pron:initial-h';
    SELECT id INTO v_u_pron_q FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:pron:question-intonation';
    SELECT id INTO v_u_cando FROM learning_units WHERE course_id=v_course AND unit_key='de:a1:can-do:greet-introduce';









    UPDATE curriculum_outcomes SET status='covered', evidence=JSON_ARRAY(JSON_OBJECT('series',1,'lesson',4,'type','mastery_transfer')) WHERE course_id=v_course AND cefr_level='A1' AND outcome_key IN ('can_do:greet_part','can_do:introduce_name','reading:short_identity','listening:first_contact','pron:initial_h','pron:question_intonation');
    UPDATE curriculum_outcomes SET status='in_progress', evidence=JSON_ARRAY(JSON_OBJECT('series',1,'lesson',2,'type','controlled_and_transfer')) WHERE course_id=v_course AND cefr_level='A1' AND outcome_key='grammar:name_patterns';
  END IF;
  COMMIT;
END$$
DELIMITER ;
CALL nova_de_v3_s001();
DROP PROCEDURE nova_de_v3_s001;
